#!/bin/bash
K3_G='k3_g_src=${BASH_SOURCE[0]:-}; k3_g_how=; if [ -z "$k3_g_src" ]; then case $- in *[ic]*) ;; *) k3_g_how=stdin ;; esac; elif [ "$k3_g_src" = "$0" ] && [ ! -f "$k3_g_src" ] && [ -r "$k3_g_src" ]; then k3_g_how=fd; fi
if [ -n "$k3_g_how" ]; then k3_g_dir=$(mktemp -d "${TMPDIR:-/tmp}/kaskad-install.XXXXXX") || { printf "%s\n" "Kaskad: не удалось создать временный каталог (mktemp -d)." "Kaskad: could not create a temporary directory (mktemp -d)." >&2; exit 1; }; case $k3_g_dir in /*) ;; *) k3_g_dir=$PWD/$k3_g_dir ;; esac
    chmod 700 "$k3_g_dir"; k3_g_f=$k3_g_dir/install.sh; { printf "#!/bin/bash\nK3_G=\047%s\047; eval \"\$K3_G\"\n" "$K3_G"; if [ "$k3_g_how" = stdin ]; then cat; else cat -- "$k3_g_src"; fi; } > "$k3_g_f"
    if [ "$(tail -n 1 "$k3_g_f")" != "# K3_EOF: конец install.sh (по этой строке установщик проверяет, что файл скачан целиком)" ] || [ -n "$(tail -c 1 "$k3_g_f")" ]; then rm -rf "$k3_g_dir"; printf "%s\n" "Kaskad: install.sh скачан не целиком — система не менялась, повторите команду установки." "Kaskad: install.sh downloaded incompletely — nothing changed, run the install command again." >&2; exit 1; fi
    chmod 700 "$k3_g_f"; export K3_BOOT_TMP=$k3_g_dir; [ "$k3_g_how" = fd ] && exec "${BASH:-bash}" "$k3_g_f" "$@"; k3_g_tty=${K3_BOOT_TTY:-/dev/tty}; if (exec < "$k3_g_tty") 2>/dev/null; then exec "${BASH:-bash}" "$k3_g_f" "$@" < "$k3_g_tty"; fi
    [ $# -gt 0 ] && exec "${BASH:-bash}" "$k3_g_f" "$@" < /dev/null; rm -rf "$k3_g_dir"; printf "%s\n" "Kaskad: при «curl … | bash» нет терминала для ответов. Запустите так:" "Kaskad: «curl … | bash» has no terminal for answers. Run it like this:" "  bash <(curl -fsSL https://raw.githubusercontent.com/potap1978/go-all/main/gokaskad/dev/install.sh)" "  curl -fsSL …/install.sh -o install.sh && bash install.sh" >&2; exit 1
fi; unset k3_g_src k3_g_how'; eval "$K3_G"
set -o pipefail

