    return nets
def _taken(ip, nets, held):
    """ip is in one of ``nets`` [(iface, network)] — not the legs kawgN; a /32 (/128) equal to ip counts only when the
    node does not hold ip itself (the far end of «peer», a host route)."""
    for d, net in nets:
        if d.startswith("kawg") or net.version != ip.version or ip not in net: continue
        if net.prefixlen == net.max_prefixlen and ip in held: continue
        return True
    return False
def _awg_ifaddr(a):
    """The Address of an AmneziaWG key (the first of the list) — an IP address of the client, without a prefix (/32,
    /128) or with one not shorter than /8 (IPv4) or /64 (IPv6), in a private network (_AWG_PRIVATE), not the address of
    that network nor its broadcast, not in the networks of the gateway nor in those of the interfaces and the routes of
    the node (an address it holds as a /32 — yes), not a router nor a name server of the node: it goes to «ip address
    replace … noprefixroute» of the leg; None — not one."""
    import ipaddress
    a = str(a or "").strip()
    if not a or "%" in a: return None
    try: i = ipaddress.ip_interface(a)
    except ValueError: return None
    n = i.network
    if n.prefixlen < _AWG_MIN_PREFIX[i.version] or i.ip.is_unspecified or i.ip.is_multicast: return None
    if not any(p.version == i.version and n.subnet_of(p) for p in map(ipaddress.ip_network, _AWG_PRIVATE)): return None
    if n.num_addresses > 2 and (i.ip == n.network_address or (i.version == 4 and i.ip == n.broadcast_address)): return None
    if any(i.ip in g for g in _gw_bases() if g.version == i.version): return None
